var fs         = global.get('fs');
var configPath = msg.configPath || 'C:/Users/Azhar/OneDrive/Desktop/flow/config.json';

if (!fs) { node.error('fs not in global context — check settings.js', msg); return null; }

var stat;
try { stat = fs.statSync(configPath); }
catch (e) { node.status({ fill:'red', shape:'ring', text:'File not found' }); return null; }

var currentMtime  = stat.mtimeMs;
var previousMtime = global.get('configMtime') || 0;

if (currentMtime === previousMtime) return null;   // silent — no change

global.set('configMtime', currentMtime);
var ts = new Date(currentMtime).toLocaleTimeString();
node.status({ fill:'yellow', shape:'dot', text:'Change @ ' + ts + ' — running...' });
node.log('[Watcher] config.json changed @ ' + ts);

msg.configPath = configPath;
msg.log        = ['⚡ Change detected @ ' + ts];
return msg;

var fs = global.get('fs');
var configPath = msg.configPath;
var log = msg.log || [];

// ─── Parse config.json ────────────────────────────────────────────
try {
    var raw = fs.readFileSync(configPath, 'utf8');
    var cfg = JSON.parse(raw);
} catch (e) {
    node.error('Cannot read/parse config.json: ' + e.message, msg);
    node.status({ fill:'red', shape:'dot', text:'Parse error: ' + e.message });
    return null;
}

if (!cfg.projectName) { node.error('config.json: "projectName" required', msg); return null; }
if (!Array.isArray(cfg.columns) || !cfg.columns.length) { node.error('config.json: "columns" required', msg); return null; }

// Check for duplicates
var seenCol = {};
for (var i = 0; i < cfg.columns.length; i++) {
    var cname = cfg.columns[i].name;
    if (seenCol[cname]) {
        node.error('Duplicate column found in config.json: ' + cname, msg);
        node.status({ fill:'red', shape:'dot', text:'Duplicate: ' + cname });
        return null;
    }
    seenCol[cname] = true;
}

// ─── Derive all paths ─────────────────────────────────────────────
var p    = cfg.projectName;
var base = cfg.baseDir || 'D:/';
if (!base.endsWith('/') && !base.endsWith('\\')) base += '/';

cfg.dbDir     = cfg.dbDir    || (base + p + '/');
cfg.dbName    = cfg.dbName   || (p + '.db');
cfg.dbTable   = cfg.dbTable  || p;
cfg.dbPath    = cfg.dbDir + cfg.dbName;
cfg.backupDir = cfg.backupDir || (cfg.dbDir + 'Backup_Data/Frequancy_Files/');
cfg.datFile   = cfg.datFile   || (cfg.dbDir + p + '.dat');
cfg.mainBackupFile = cfg.mainBackupFile || (cfg.dbDir + 'Backup_Data/MasterBackup.dat');

cfg.stationName = (cfg.toa5 && cfg.toa5.stationName) ? cfg.toa5.stationName : p;

if (cfg.toa5 && Array.isArray(cfg.toa5.frequencies)) {
    cfg.backupFiles = cfg.toa5.frequencies.map(function(f) {
        return {
            seconds: f.seconds,
            fileName: cfg.stationName + '-' + f.name.trim() + '.dat',
            suffix: f.stationSuffix
        };
    });
} else if (!Array.isArray(cfg.backupFiles)) {
    cfg.backupFiles = [
        { seconds: 60,  fileName: cfg.stationName + '-1_min.dat', suffix: '1minute'  },
        { seconds: 300, fileName: cfg.stationName + '-5_min.dat', suffix: '5minute'  },
        { seconds: 600, fileName: cfg.stationName + '-10_min.dat', suffix: '10minute' }
    ];
}

cfg.nodeRedFlowsFile = cfg.nodeRedFlowsFile || 'C:/Users/Azhar/.node-red/flows.json';
cfg.nodeRedCredFile  = cfg.nodeRedCredFile  || 'C:/Users/Azhar/.node-red/flows_cred.json';
cfg.ftpNodeId        = (cfg.ftp && cfg.ftp.nodeId) ? cfg.ftp.nodeId : 'ftp_config_server';

// ─── Build TOA5 header ────────────────────────────────────────────
var sn   = cfg.stationName;
cfg.hdr2 = cfg.columns.map(function(c){ return '"'+c.name+'"'; }).join(',');
cfg.hdr3 = cfg.columns.map(function(c){ return '"'+(c.unit||'')+'"'; }).join(',');
cfg.hdr4 = cfg.columns.map(function(c){ return '"'+(c.sampling||'')+'"'; }).join(',');

// ─── Load previous config from global context ─────────────────────
var prevConfig = global.get('lastAppliedConfig') || null;

log.push('✓ Parsed: ' + p + ' (' + cfg.columns.length + ' cols)');
if (prevConfig) log.push('  Previous: ' + prevConfig.projectName);
node.status({ fill:'blue', shape:'dot', text:'Parsed: ' + p });

msg.config     = cfg;
msg.prevConfig = prevConfig;
msg.log        = log;
return msg;

var fs      = global.get('fs');
var sqlite3 = global.get('sqlite3');
var cfg     = msg.config;
var prev    = msg.prevConfig;
var log     = msg.log || [];

if (!sqlite3) { node.error('sqlite3 not in global context — check settings.js', msg); return null; }

// ═══════════════════════════════════════════════════════════════════
// PART A: Detect & handle all renames independently
// ═══════════════════════════════════════════════════════════════════
var renameTable = null;
var renameCols  = [];
var dropCols    = [];

if (prev) {
    var dirChanged   = prev.dbDir   && prev.dbDir   !== cfg.dbDir;
    var nameChanged  = prev.dbPath  && prev.dbPath  !== cfg.dbPath;
    var tableChanged = prev.dbTable && prev.dbTable !== cfg.dbTable;
    var projChanged  = prev.projectName && prev.projectName !== cfg.projectName;

    // ── 1. Rename project folder ──────────────────────────────────
    if (dirChanged) {
        if (fs.existsSync(prev.dbDir) && !fs.existsSync(cfg.dbDir)) {
            try {
                fs.renameSync(prev.dbDir, cfg.dbDir);
                log.push('✓ Folder renamed: ' + prev.dbDir + ' → ' + cfg.dbDir);
            } catch (e) { log.push('✗ Folder rename: ' + e.message); }
        } else if (fs.existsSync(cfg.dbDir)) {
            log.push('  Target folder already exists: ' + cfg.dbDir);
        }
    }

    // ── 2. Rename DB file ─────────────────────────────────────────
    if (nameChanged) {
        var oldDbLocation = dirChanged
            ? (cfg.dbDir + (prev.dbName || (prev.projectName + '.db')))
            : prev.dbPath;
        if (fs.existsSync(oldDbLocation) && !fs.existsSync(cfg.dbPath)) {
            try {
                fs.renameSync(oldDbLocation, cfg.dbPath);
                log.push('✓ DB file renamed: ' + (prev.dbName||'old') + ' → ' + cfg.dbName);
            } catch (e) { log.push('✗ DB file rename: ' + e.message); }
        } else if (fs.existsSync(cfg.dbPath)) {
            log.push('  DB target already exists: ' + cfg.dbPath);
        }
    }

    // ── 3. Rename .dat file ───────────────────────────────────────
    if (projChanged || dirChanged) {
        var oldDatName = (prev.projectName || cfg.projectName) + '.dat';
        var oldDatLoc  = dirChanged ? (cfg.dbDir + oldDatName) : (prev.dbDir + oldDatName);
        if (fs.existsSync(oldDatLoc) && oldDatLoc !== cfg.datFile) {
            try {
                fs.renameSync(oldDatLoc, cfg.datFile);
                log.push('✓ .dat renamed → ' + cfg.datFile.split('/').pop());
            } catch (e) { log.push('✗ .dat rename: ' + e.message); }
        }
    }

    // ── 4. Rename backup files ────────────────────────────────────
    var scanDir = fs.existsSync(cfg.backupDir) ? cfg.backupDir : (prev.backupDir || '');
    if (scanDir && fs.existsSync(scanDir)) {
        if (prev.backupFiles && cfg.backupFiles) {
            cfg.backupFiles.forEach(function(bf) {
                var prevBf = prev.backupFiles.find(function(pb) { return pb.seconds === bf.seconds; });
                if (prevBf && prevBf.fileName !== bf.fileName) {
                    var oldPath = scanDir + prevBf.fileName;
                    var newPath = scanDir + bf.fileName;
                    if (fs.existsSync(oldPath) && !fs.existsSync(newPath)) {
                        try {
                            fs.renameSync(oldPath, newPath);
                            log.push('✓ Backup renamed: ' + prevBf.fileName + ' → ' + bf.fileName);

                            // Rename on FTP natively
                            if (cfg.ftp && typeof FtpClient !== 'undefined') {
                                var rDir = cfg.ftp.remoteDir || '/';
                                if (!rDir.endsWith('/')) rDir += '/';
                                var oldRemote = rDir + prevBf.fileName;
                                var newRemote = rDir + bf.fileName;

                                var c = new FtpClient();
                                c.on('ready', function() {
                                    c.rename(oldRemote, newRemote, function(err) {
                                        if (err) node.warn('FTP rename err: ' + err.message);
                                        else node.warn('✓ FTP renamed: ' + prevBf.fileName + ' to ' + bf.fileName);
                                        c.end();
                                    });
                                });
                                c.on('error', function(err) {
                                    node.warn('FTP connection err: ' + err.message);
                                });
                                c.connect({
                                    host: cfg.ftp.host,
                                    port: cfg.ftp.port || 21,
                                    user: cfg.ftp.user,
                                    password: cfg.ftp.password,
                                    keepalive: 10000,
                                    pasvTimeout: 10000
                                });
                            }
                        } catch (e) { log.push('✗ Backup rename: ' + e.message); }
                    }
                }
            });
        }
    }

    // ── 5. Flag SQLite table rename ───────────────────────────────
    if (tableChanged) {
        renameTable = { from: prev.dbTable, to: cfg.dbTable };
        log.push('🔄 Table rename: "' + prev.dbTable + '" → "' + cfg.dbTable + '"');
    }

    // ── 6. Detect column renames and drops ──
    if (prev.columns && Array.isArray(prev.columns)) {
        var oldNames = prev.columns.map(function(c) { return c.name; });
        var newNames = cfg.columns.map(function(c) { return c.name; });

        var minLen = Math.min(oldNames.length, newNames.length);
        for (var i = 0; i < minLen; i++) {
            var oldN = oldNames[i];
            var newN = newNames[i];
            if (oldN !== newN) {
                if (newNames.indexOf(oldN) === -1 && oldNames.indexOf(newN) === -1) {
                    renameCols.push({ from: oldN, to: newN });
                    log.push('🔄 Column rename pending: "' + oldN + '" → "' + newN + '"');
                    oldNames[i] = null;
                    newNames[i] = null;
                }
            }
        }

        for (var i = 0; i < oldNames.length; i++) {
            if (oldNames[i] !== null && newNames.indexOf(oldNames[i]) === -1) {
                dropCols.push(oldNames[i]);
                log.push('🗑️ Column drop pending: "' + oldNames[i] + '"');
            }
        }
    }
}

// ═══════════════════════════════════════════════════════════════════
// PART B: Ensure directories exist
// ═══════════════════════════════════════════════════════════════════
function ensureDir(d) {
    try   { fs.mkdirSync(d, { recursive: true }); }
    catch (e) { log.push('✗ mkdirSync ' + d + ': ' + e.message); }
}
ensureDir(cfg.dbDir);
ensureDir(cfg.backupDir);

// ═══════════════════════════════════════════════════════════════════
// PART C: Open SQLite, apply renames, CREATE TABLE, sync new cols
// ═══════════════════════════════════════════════════════════════════
var colDefs   = cfg.columns.map(function(c){ return '    "'+c.name+'" '+(c.type||'TEXT'); }).join(',\n');
var createSQL = 'CREATE TABLE IF NOT EXISTS "'+cfg.dbTable+'" (\n'+colDefs+'\n);';
var pragmaSQL = 'PRAGMA table_info("'+cfg.dbTable+'");';

var sqlite3v = sqlite3.verbose();
var db = new sqlite3v.Database(
    cfg.dbPath,
    sqlite3v.OPEN_READWRITE | sqlite3v.OPEN_CREATE,
    function(openErr) {
        if (openErr) { node.error('DB open failed: ' + openErr.message, msg); return; }
        log.push('✓ DB: ' + cfg.dbPath);

        // Step 1: rename table if project was renamed
        function doTableRename(cb) {
            if (!renameTable) return cb();
            db.run('ALTER TABLE "'+renameTable.from+'" RENAME TO "'+renameTable.to+'";', function(err) {
                if (err) log.push('  Table rename skipped: ' + err.message);
                else     log.push('✓ Table renamed: "'+renameTable.from+'" → "'+renameTable.to+'"');
                cb();
            });
        }

        // Step 1.5: rename columns
        function doColRenames(cb) {
            if (!renameCols.length) return cb();
            // ALTER TABLE RENAME COLUMN is supported in newer SQLite versions (3.25.0+)
            var i = 0;
            function next() {
                if (i >= renameCols.length) return cb();
                var r = renameCols[i++];
                db.run('ALTER TABLE "'+cfg.dbTable+'" RENAME COLUMN "'+r.from+'" TO "'+r.to+'";', function(err) {
                    if (err) log.push('✗ Col rename "'+r.from+'": ' + err.message);
                    else     log.push('✓ Col renamed: "'+r.from+'" → "'+r.to+'"');
                    next();
                });
            }
            next();
        }


        // Step 1.8: drop columns
        function doColDrops(cb) {
            if (!dropCols.length) return cb();
            var i = 0;
            function next() {
                if (i >= dropCols.length) return cb();
                var c = dropCols[i++];
                db.run('ALTER TABLE "'+cfg.dbTable+'" DROP COLUMN "'+c+'";', function(err) {
                    if (err) log.push('✗ Col drop "'+c+'": ' + err.message);
                    else     log.push('✓ Col dropped: "'+c+'"');
                    next();
                });
            }
            next();
        }

        // Step 2: CREATE TABLE IF NOT EXISTS
        function doCreate(cb) {
            db.run(createSQL, function(err) {
                if (err) { db.close(); node.error('CREATE TABLE: ' + err.message, msg); return; }
                log.push('✓ Table "'+cfg.dbTable+'" ready');
                cb();
            });
        }

        // Step 3: Add new columns (if any weren't caught by rename)
        function doAlter(cb) {
            db.all(pragmaSQL, function(err, rows) {
                if (err) { log.push('✗ PRAGMA: ' + err.message); return cb(); }
                var existing = rows.map(function(r){ return r.name; });
                var alters   = [];
                cfg.columns.forEach(function(c) {
                    if (existing.indexOf(c.name) === -1)
                        alters.push('ALTER TABLE "'+cfg.dbTable+'" ADD COLUMN "'+c.name+'" '+(c.type||'TEXT')+';');
                });
                if (!alters.length) { log.push('✓ Schema up to date'); return cb(); }
                var i = 0;
                function next() {
                    if (i >= alters.length) {
                        log.push('✓ Added ' + alters.length + ' new column(s)');
                        return cb();
                    }
                    db.run(alters[i++], function(e) {
                        if (e) log.push('✗ ALTER: ' + e.message);
                        next();
                    });
                }
                next();
            });
        }

        doTableRename(function() {
            doColRenames(function() {
                doColDrops(function() {
                    doCreate(function() {
                    doAlter(function() {
                        db.close();
                        msg.log = log;
                        node.send(msg);
                        });
                    });
                });
            });
        });
    }
);

return null;  // async

var fs  = global.get('fs');
var cfg = msg.config;
var log = msg.log || [];

// ═══════════════════════════════════════════
// A: Update flows.json
// ═══════════════════════════════════════════
try {
    var raw     = fs.readFileSync(cfg.nodeRedFlowsFile, 'utf8');
    var flows   = JSON.parse(raw);
    var changed = false;

    flows.forEach(function(n) {
        // sqlitedb config nodes
        if (n.type === 'sqlitedb' && n.db !== cfg.dbPath) {
            log.push('sqlitedb [' + (n.name||n.id) + ']: → ' + cfg.dbPath);
            n.db   = cfg.dbPath;
            n.mode = n.mode || 'RWC';
            changed = true;
        }
        // FTP config node
        if (cfg.ftp && n.id === cfg.ftpNodeId && n.type === 'ftp') {
            var f = cfg.ftp;
            if (f.host !== undefined && n.host !== f.host) { n.host = f.host; log.push('FTP host → '+f.host); changed = true; }
            if (f.port !== undefined && String(n.port) !== String(f.port)) { n.port = String(f.port); changed = true; }
            if (f.user !== undefined && n.user !== f.user) { n.user = f.user; log.push('FTP user → '+f.user); changed = true; }
            if (f.name !== undefined && n.name !== f.name) { n.name = f.name; changed = true; }
        }
    });

    if (changed) {
        var bak = cfg.nodeRedFlowsFile + '.' + Date.now() + '.bak';
        fs.copyFileSync(cfg.nodeRedFlowsFile, bak);
        fs.writeFileSync(cfg.nodeRedFlowsFile, JSON.stringify(flows, null, 4), 'utf8');
        log.push('✓ flows.json updated (backup created)');
        log.push('⚠️  Restart Node-RED to activate new DB path');
    } else {
        log.push('✓ flows.json — no changes needed');
    }
} catch (e) {
    log.push('✗ flows.json: ' + e.message);
}

// ═══════════════════════════════════════════
// B: FTP password
// ═══════════════════════════════════════════
try {
    if (cfg.ftp && cfg.ftp.password) {
        var creds = {};
        creds[cfg.ftpNodeId] = { password: cfg.ftp.password };
        fs.writeFileSync(cfg.nodeRedCredFile, JSON.stringify(creds, null, 4), 'utf8');
        log.push('✓ FTP password saved');
    }
} catch (e) { log.push('✗ flows_cred.json: ' + e.message); }

// ═══════════════════════════════════════════
// C: Create .dat files if still missing
// ═══════════════════════════════════════════
function getHeader(suffix) {
    var s = cfg.stationName + (suffix ? '-' + suffix : '');
    var hdr1 = '"TOA5","'+s+'","'+s+'","'+s+'","'+s+'","'+s+'","'+s+'","'+s+'"';
    return hdr1 + '\n' + cfg.hdr2 + '\n' + cfg.hdr3 + '\n' + cfg.hdr4 + '\n';
}

function updateDatHeaders(p, suffix) {
    try {
        var header = getHeader(suffix);
        if (!fs.existsSync(p)) {
            fs.writeFileSync(p, header, 'utf8');
            log.push('✓ Created .dat: ' + p.split('/').pop());
        } else {
            var content = fs.readFileSync(p, 'utf8');
            var lines = content.replace(/\r\n/g, '\n').split('\n');
            if (lines.length >= 4) {
                var oldHdr = lines.slice(0, 4).join('\n') + '\n';
                var newHdrNorm = header.replace(/\r\n/g, '\n');
                if (oldHdr !== newHdrNorm) {
                    var dataLines = lines.slice(4).join('\n');
                    fs.writeFileSync(p, newHdrNorm + dataLines, 'utf8');
                    log.push('✓ Updated headers: ' + p.split('/').pop());
                }
            }
        }
    } catch (e) { log.push('✗ .dat: ' + p + ' — ' + e.message); }
}

updateDatHeaders(cfg.datFile, '');
if (cfg.mainBackupFile) {
    var mainDir = cfg.mainBackupFile.substring(0, cfg.mainBackupFile.lastIndexOf('/'));
    try { fs.mkdirSync(mainDir, { recursive: true }); } catch(e) {}
    updateDatHeaders(cfg.mainBackupFile, 'Master');
}
cfg.backupFiles.forEach(function(bf) {
    updateDatHeaders(cfg.backupDir + bf.fileName, bf.suffix || '');
});

// ═══════════════════════════════════════════
// D: Save applied config to global context
//    (needed for rename detection on next change)
// ═══════════════════════════════════════════
global.set('lastAppliedConfig', {
    projectName: cfg.projectName,
    dbDir:       cfg.dbDir,
    dbName:      cfg.dbName,
    dbTable:     cfg.dbTable,
    dbPath:      cfg.dbPath,
    backupDir:   cfg.backupDir,
    datFile:     cfg.datFile,
    mainBackupFile: cfg.mainBackupFile,
    backupFiles: cfg.backupFiles,
    ftp:         cfg.ftp,
    hdr2:        cfg.hdr2,
    hdr3:        cfg.hdr3,
    hdr4:        cfg.hdr4,
    stationName: cfg.stationName,
    columns:     cfg.columns
});
log.push('✓ State saved to global context');

// ═══════════════════════════════════════════
// OUTPUT
// ═══════════════════════════════════════════
var errors   = log.filter(function(l){ return l.charAt(0) === '✗'; }).length;
var warnings = log.filter(function(l){ return l.charAt(0) === '⚠'; }).length;
var ts       = new Date().toLocaleTimeString();

msg.payload = {
    status:      errors ? 'PARTIAL' : 'SUCCESS',
    appliedAt:   ts,
    projectName: cfg.projectName,
    dbPath:      cfg.dbPath,
    dbTable:     cfg.dbTable,
    columns:     cfg.columns.length,
    errors:      errors,
    warnings:    warnings,
    log:         log
};

node.status({
    fill:  errors ? 'red' : (warnings ? 'yellow' : 'green'),
    shape: 'dot',
    text:  (errors ? '✗ '+errors+' err' : '✓ Applied') + ' @ ' + ts + ' | ' + cfg.projectName
});

return msg;

var sqlite3 = global.get('sqlite3');
var fs = global.get('fs');
var cfg = global.get('lastAppliedConfig');
var freqSeconds = parseInt(msg.topic) || 60;

if (!cfg || !sqlite3 || !fs) {
    node.status({fill:'red', shape:'ring', text:'Config/FS not ready'});
    return null;
}

var cols = [];
var vals = [];
var params = [];
var csvLineArr = [];

var recordCount = global.get('recordCount') || 0;
recordCount++;
global.set('recordCount', recordCount);

cfg.columns.forEach(function(c) {
    cols.push('"' + c.name + '"');

    var upper = c.name.toUpperCase();
    var val;
    if (upper === 'TIMESTAMP') {
        var d = new Date();
        var yyyy = d.getFullYear();
        var mon = String(d.getMonth() + 1).padStart(2, '0');
        var dd = String(d.getDate()).padStart(2, '0');
        var hh = String(d.getHours()).padStart(2, '0');
        var mi = String(d.getMinutes()).padStart(2, '0');
        val = yyyy + '-' + mon + '-' + dd + ' ' + hh + ':' + mi + ':00';
        csvLineArr.push('"' + val + '"');
    } else if (upper.indexOf('RECORD') > -1) {
        val = recordCount;
        csvLineArr.push(val);
    } else if (c.type === 'REAL') {
        val = +(Math.random() * 500).toFixed(2);
        csvLineArr.push(val);
    } else if (c.type === 'INTEGER') {
        val = Math.floor(Math.random() * 100);
        csvLineArr.push(val);
    } else {
        // The user asked to keep numbers instead of Normal/OK for TEXT columns
        val = Math.floor(Math.random() * 10000000000).toString();
        csvLineArr.push('"' + val + '"');
    }
    params.push(val);
    vals.push('?');
});

var sql = 'INSERT INTO "' + cfg.dbTable + '" (' + cols.join(',') + ') VALUES (' + vals.join(',') + ');';

// Robustness: ensure folders exist just in case they were manually deleted
try { fs.mkdirSync(cfg.dbDir, { recursive: true }); } catch(e) {}
try { fs.mkdirSync(cfg.backupDir, { recursive: true }); } catch(e) {}
if (cfg.mainBackupFile) {
    try { fs.mkdirSync(cfg.mainBackupFile.substring(0, cfg.mainBackupFile.lastIndexOf('/')), { recursive: true }); } catch(e) {}
}

var db = new sqlite3.Database(cfg.dbPath, sqlite3.OPEN_READWRITE | sqlite3.OPEN_CREATE, function(err) {
    if (err) {
        node.error('DB Open Error: ' + err.message, msg);
        node.status({fill:'red', shape:'dot', text:'DB error'});
        return;
    }
    db.run(sql, params, function(err) {
        if (err) {
            node.error('Insert Error: ' + err.message, msg);
            node.status({fill:'red', shape:'dot', text:'Insert error'});
        } else {
            node.status({fill:'green', shape:'dot', text:'Inserted record ' + recordCount});

            var logMsg = 'Inserted 1 row into DB';
            var backupFile = cfg.backupFiles.find(function(bf) { return bf.seconds === freqSeconds; });
            if (backupFile) {
                var datPath = cfg.backupDir + backupFile.fileName;
                try {
                    var csvStr = csvLineArr.join(',') + '\n';
                    fs.appendFileSync(datPath, csvStr, 'utf8');
                    logMsg += ' & appended to ' + backupFile.fileName;

                    // Prepare FTP upload
                    if (!cfg.ftp) {
                        try {
                            var tmpCfg = JSON.parse(fs.readFileSync('C:/Users/Azhar/OneDrive/Desktop/flow/config.json', 'utf8'));
                            cfg.ftp = tmpCfg.ftp;
                        } catch(e) {}
                    }
                    if (cfg.ftp) {
                        msg.localFilename = datPath;
                        var rDir = cfg.ftp.remoteDir || '/';
                        if (!rDir.endsWith('/')) rDir += '/';
                        msg.filename = rDir + backupFile.fileName;
                    }
                } catch (e) {
                    node.error('File Append Error: ' + e.message, msg);
                }
            }

            if (cfg.mainBackupFile) {
                try {
                    var csvStr = csvLineArr.join(',') + '\n';
                    fs.appendFileSync(cfg.mainBackupFile, csvStr, 'utf8');
                    logMsg += ' & appended to MasterBackup';
                } catch (e) {
                    node.error('Master File Append Error: ' + e.message, msg);
                }
            }

            msg.payload = logMsg;
            node.send(msg);
        }
        db.close();
    });
});

return null;

var freq = parseInt(msg.topic);
if (freq) {
    global.set('activeFrequency', freq);
    global.set('lastRun', Date.now());
    node.status({fill:"blue", shape:"dot", text:"Active: " + freq + "s"});
    return msg;
}
return null;

var activeFreq = global.get('activeFrequency') || 60; // default 1 min
var lastRun = global.get('lastRun') || 0;
var now = Date.now();

if (now - lastRun >= activeFreq * 1000) {
    global.set('lastRun', now);
    msg.topic = activeFreq.toString();
    node.status({fill:"green", shape:"dot", text:"Fired at " + activeFreq + "s"});
    return msg;
} else {
    var remaining = Math.ceil(activeFreq - (now - lastRun)/1000);
    node.status({fill:"grey", shape:"dot", text:"Next in " + remaining + "s | Freq: " + activeFreq + "s"});
    return null;
}
